    90	    struct Unreachable;
    91	
    92	    impl Hittable for Unreachable {
    93	        fn hit(&self, _ray: &Ray, _t_min: f64, _t_max: f64) -> Option<HitRecord> {
    94	            panic!("the list tests an object whose box the ray misses");
    95	        }
    96	
    97	        fn bounding_box(&self) -> Option<Aabb> {
    98	            Some(Aabb::new(
    99	                Vec3::new(10.0, 10.0, -6.0),
   100	                Vec3::new(11.0, 11.0, -5.0),
   101	            ))
   102	        }
   103	    }
   104	
   105	    #[test]
   106	    fn the_list_tests_an_object_without_a_box_and_skips_one_whose_box_the_ray_misses() {
   107	        let mut world = HittableList::default();
   108	        world.add(Box::new(Unreachable));
   109	        world.add(Box::new(Plane::new(
   110	            Vec3::new(0.0, 0.0, -1.0),
   111	            Vec3::new(0.0, 0.0, 1.0),
   112	        )));
   113	        let ray = Ray::new(Vec3::new(0.0, 0.0, 0.0), Vec3::new(0.0, 0.0, -1.0));
   114	        let hit = world
   115	            .hit(&ray, 0.001, f64::INFINITY)
   116	            .expect("the plane is hit");
   117	        assert!((hit.t - 1.0).abs() < 1e-9);
   118	    }
   119	}
