     1	//! Render a fixed scene and write it to a file as a PNG or PPM image.
     2	
     3	mod aabb;
     4	mod camera;
     5	mod hittable;
     6	#[allow(dead_code)]
     7	mod plane;
     8	mod png;
     9	mod ray;
    10	#[allow(dead_code)]
    11	mod rng;
    12	mod sphere;
    13	mod triangle;
    14	mod vec3;
    15	
    16	use std::fs;
    17	use std::io::{self, Write};
    18	use std::path::{Path, PathBuf};
    19	
    20	use camera::Camera;
    21	use hittable::{Hittable, HittableList};
    22	use ray::Ray;
    23	use sphere::Sphere;
    24	use triangle::Triangle;
    25	use vec3::{Colour, Vec3};
    26	
    27	const DEFAULT_WIDTH: usize = 400;
    28	const DEFAULT_HEIGHT: usize = 200;
    29	const DEFAULT_SAMPLES: usize = 16;
    30	const DEFAULT_OUTPUT: &str = "render.png";
    31	
    32	const USAGE: &str = "usage: toy-raytracer [--width <pixels>] [--height <pixels>] [--samples <count>] [--output <path>] [--format png|ppm]";
    33	
    34	#[derive(Clone, Copy)]
    35	enum Format {
    36	    Png,
    37	    Ppm,
    38	}
    39	
    40	struct Settings {
    41	    width: usize,
    42	    height: usize,
    43	    samples: usize,
    44	    output: PathBuf,
    45	    format: Format,
    46	}
    47	
    48	/// The colour seen along a ray: the surface normal where it hits, the sky gradient otherwise.
    49	fn ray_colour(ray: &Ray, world: &dyn Hittable) -> Colour {
    50	    if let Some(hit) = world.hit(ray, 0.001, f64::INFINITY) {
    51	        return (hit.normal + Vec3::new(1.0, 1.0, 1.0)) * 0.5;
    52	    }
    53	    let t = 0.5 * (ray.direction.unit().y + 1.0);
    54	    Vec3::new(1.0, 1.0, 1.0) * (1.0 - t) + Vec3::new(0.5, 0.7, 1.0) * t
    55	}
    56	
    57	fn scene() -> HittableList {
    58	    let mut world = HittableList::default();
    59	    world.add(Box::new(Sphere::new(Vec3::new(0.0, 0.0, -1.0), 0.5)));
    60	    world.add(Box::new(Sphere::new(Vec3::new(0.0, -100.5, -1.0), 100.0)));
    61	    world.add(Box::new(Triangle::new(
    62	        Vec3::new(0.6, 0.15, -1.0),
    63	        Vec3::new(1.95, 0.15, -1.0),
    64	        Vec3::new(1.275, 0.92, -1.0),
    65	    )));
    66	    world
    67	}
    68	
    69	/// Every pixel's colour, row by row from the top, each pixel averaging `samples` rays, with the
    70	/// share of finished rows reported on standard error.
    71	fn render(width: usize, height: usize, samples: usize) -> Vec<Colour> {
    72	    let world = scene();
    73	    let camera = Camera::new(width as f64 / height as f64);
    74	    let mut pixels = Vec::with_capacity(width * height);
    75	    for row in (0..height).rev() {
    76	        for column in 0..width {
    77	            let u = column as f64 / (width - 1) as f64;
    78	            let v = row as f64 / (height - 1) as f64;
    79	            let ray = camera.ray(u, v);
    80	            let mut colour = Colour::new(0.0, 0.0, 0.0);
    81	            for _ in 0..samples {
    82	                colour = colour + ray_colour(&ray, &world);
    83	            }
    84	            pixels.push(colour / samples as f64);
    85	        }
    86	        let done = height - row;
    87	        eprint!("\r{}%", done * 100 / height);
    88	    }
    89	    eprintln!();
    90	    pixels
    91	}
    92	
    93	pub(crate) fn to_byte(channel: f64) -> u8 {
    94	    (255.999 * channel.clamp(0.0, 1.0)) as u8
    95	}
    96	
    97	fn write_ppm(
    98	    out: &mut impl Write,
    99	    width: usize,
   100	    height: usize,
   101	    pixels: &[Colour],
   102	) -> io::Result<()> {
   103	    writeln!(out, "P3\n{width} {height}\n255")?;
   104	    for pixel in pixels {
   105	        writeln!(
   106	            out,
   107	            "{} {} {}",
   108	            to_byte(pixel.x),
   109	            to_byte(pixel.y),
   110	            to_byte(pixel.z)
   111	        )?;
   112	    }
   113	    Ok(())
   114	}
   115	
   116	/// Resolve the arguments into one set of settings before any rendering starts.
   117	fn parse_args(args: &[String]) -> Result<Settings, String> {
   118	    let mut width = DEFAULT_WIDTH;
   119	    let mut height = DEFAULT_HEIGHT;
   120	    let mut samples = DEFAULT_SAMPLES;
   121	    let mut output = PathBuf::from(DEFAULT_OUTPUT);
   122	    let mut explicit_format = None;
   123	
   124	    let mut index = 0;
   125	    while index < args.len() {
   126	        let option = args[index].as_str();
   127	        let value = || {
   128	            args.get(index + 1)
   129	                .map(String::as_str)
   130	                .ok_or_else(|| format!("{option} needs a value"))
   131	        };
   132	        match option {
   133	            "--width" => width = parse_dimension(option, value()?)?,
   134	            "--height" => height = parse_dimension(option, value()?)?,
   135	            "--samples" => {
   136	                let value = value()?;
   137	                let count = value
   138	                    .parse::<usize>()
   139	                    .map_err(|_| format!("--samples: {value:?} is not a whole number"))?;
   140	                if count < 1 {
   141	                    return Err(format!("--samples: {value:?} is less than 1"));
   142	                }
   143	                samples = count;
   144	            }
   145	            "--output" => output = PathBuf::from(value()?),
   146	            "--format" => {
   147	                explicit_format = Some(match value()? {
   148	                    "png" => Format::Png,
   149	                    "ppm" => Format::Ppm,
   150	                    other => return Err(format!("--format: unrecognised format {other:?}")),
   151	                });
   152	            }
   153	            other => return Err(format!("unknown option {other:?}")),
   154	        }
   155	        index += 2;
   156	    }
   157	
   158	    let format = resolve_format(explicit_format, &output)?;
   159	    Ok(Settings {
   160	        width,
   161	        height,
   162	        samples,
   163	        output,
   164	        format,
   165	    })
   166	}
   167	
   168	/// A pixel dimension, which must parse as a whole number of at least 2.
   169	fn parse_dimension(option: &str, value: &str) -> Result<usize, String> {
   170	    let dimension = value
   171	        .parse::<usize>()
   172	        .map_err(|_| format!("{option}: {value:?} is not a whole number"))?;
   173	    if dimension < 2 {
   174	        return Err(format!("{option}: {value:?} is less than 2"));
   175	    }
   176	    Ok(dimension)
   177	}
   178	
   179	/// An explicit format, or the one named by the output file's extension.
   180	fn resolve_format(explicit: Option<Format>, output: &Path) -> Result<Format, String> {
   181	    if let Some(format) = explicit {
   182	        return Ok(format);
   183	    }
   184	    match output.extension().and_then(|extension| extension.to_str()) {
   185	        Some("png") => Ok(Format::Png),
   186	        Some("ppm") => Ok(Format::Ppm),
   187	        _ => Err(format!(
   188	            "{}: output name has no png or ppm extension and no --format is given",
   189	            output.display()
   190	        )),
   191	    }
   192	}
   193	
   194	fn run(settings: &Settings) -> io::Result<()> {
   195	    let pixels = render(settings.width, settings.height, settings.samples);
   196	    let mut bytes = Vec::new();
   197	    match settings.format {
   198	        Format::Png => png::write_png(&mut bytes, settings.width, settings.height, &pixels)?,
   199	        Format::Ppm => write_ppm(&mut bytes, settings.width, settings.height, &pixels)?,
   200	    }
   201	    fs::write(&settings.output, bytes)
   202	}
   203	
   204	fn main() {
   205	    let args: Vec<String> = std::env::args().skip(1).collect();
   206	    let settings = match parse_args(&args) {
   207	        Ok(settings) => settings,
   208	        Err(message) => {
   209	            eprintln!("error: {message}");
   210	            eprintln!("{USAGE}");
   211	            std::process::exit(2);
   212	        }
   213	    };
   214	    if let Err(error) = run(&settings) {
   215	        eprintln!("error: {error}");
   216	        std::process::exit(1);
   217	    }
   218	}
   219	
   220	#[cfg(test)]
   221	mod tests {
   222	    use super::*;
   223	
   224	    #[test]
   225	    fn the_center_pixel_shows_the_sphere_facing_the_camera() {
   226	        let pixels = render(200, 100, 16);
   227	        let center = pixels[50 * 200 + 100];
   228	        assert!(center.z > 0.9, "the normal faces the camera: {center:?}");
   229	    }
   230	
   231	    #[test]
   232	    fn the_top_row_is_sky() {
   233	        let pixels = render(200, 100, 16);
   234	        assert!(pixels[0].z > pixels[0].x, "the sky is bluer than it is red");
   235	    }
   236	}
