    60	        let sphere = Sphere::new(Vec3::new(0.0, 0.0, -2.0), 0.5);
    61	        let ray = Ray::new(Vec3::new(0.0, 0.0, 0.0), Vec3::new(0.0, 0.0, -1.0));
    62	        let hit = sphere
