    88	            .expect("the ray hits");
    89	        assert!((hit.u - 0.25).abs() < 1e-9);
    90	        assert!((hit.v - 0.5).abs() < 1e-9);
    91	    }
    92	
    93	    #[test]
    94	    fn a_ray_beside_the_sphere_misses() {
    95	        let sphere = Sphere::new(Vec3::new(0.0, 0.0, -2.0), 0.5);
    96	        let ray = Ray::new(Vec3::new(1.0, 0.0, 0.0), Vec3::new(0.0, 0.0, -1.0));
    97	        assert!(sphere.hit(&ray, 0.001, f64::INFINITY).is_none());
    98	    }
