     6	/// The box between two opposite corners.
     7	pub struct Aabb {
     8	    pub min: Vec3,
     9	    pub max: Vec3,
    10	}
    11	
    12	impl Aabb {
    13	    /// Build a box from opposite corners, `min` low on every axis.
    14	    pub fn new(min: Vec3, max: Vec3) -> Self {
    15	        Aabb { min, max }
    16	    }
    17	
    18	    /// Report whether the ray crosses the box with some `t` in `t_min..t_max`.
    19	    pub fn hit(&self, ray: &Ray, t_min: f64, t_max: f64) -> bool {
    20	        let origin = [ray.origin.x, ray.origin.y, ray.origin.z];
    21	        let direction = [ray.direction.x, ray.direction.y, ray.direction.z];
    22	        let min = [self.min.x, self.min.y, self.min.z];
    23	        let max = [self.max.x, self.max.y, self.max.z];
    24	        let mut t_enter = t_min;
    25	        let mut t_exit = t_max;
    26	        for axis in 0..3 {
    27	            if direction[axis] == 0.0 {
    28	                if origin[axis] < min[axis] || origin[axis] > max[axis] {
    29	                    return false;
    30	                }
    31	                continue;
    32	            }
    33	            let inverse = 1.0 / direction[axis];
    34	            let mut near = (min[axis] - origin[axis]) * inverse;
    35	            let mut far = (max[axis] - origin[axis]) * inverse;
    36	            if near > far {
    37	                (near, far) = (far, near);
    38	            }
    39	            t_enter = t_enter.max(near);
    40	            t_exit = t_exit.min(far);
    41	            if t_enter > t_exit {
    42	                return false;
    43	            }
    44	        }
    45	        true
    46	    }
    47	}
