     9	/// Where a ray hit a surface: the distance along the ray, the point, the normal facing the ray, the
    10	/// face side, the texture coordinates and the material of the object.
    11	pub struct HitRecord {
    12	    pub t: f64,
    13	    pub point: Vec3,
    14	    /// Faces against the incoming ray.
    15	    pub normal: Vec3,
    16	    pub front_face: bool,
    17	    #[allow(dead_code)]
    18	    pub u: f64,
    19	    #[allow(dead_code)]
    20	    pub v: f64,
    21	    pub material: Rc<dyn Material>,
    22	}
    23	
    24	impl HitRecord {
    25	    /// A record for a hit by `ray` at `point`, with `outward_normal` facing away from the object.
    26	    pub fn new(
    27	        ray: &Ray,
    28	        t: f64,
    29	        point: Vec3,
    30	        outward_normal: Vec3,
    31	        u: f64,
    32	        v: f64,
    33	        material: Rc<dyn Material>,
    34	    ) -> Self {
    35	        let front_face = ray.direction.dot(outward_normal) < 0.0;
    36	        HitRecord {
    37	            t,
    38	            point,
    39	            normal: if front_face {
    40	                outward_normal
    41	            } else {
    42	                -outward_normal
    43	            },
    44	            front_face,
    45	            u,
    46	            v,
    47	            material,
    48	        }
    49	    }
    50	}
    51	
    52	pub trait Hittable {
    53	    /// The nearest hit with `t` in `t_min..t_max`, if any.
    54	    fn hit(&self, ray: &Ray, t_min: f64, t_max: f64) -> Option<HitRecord>;
    55	}
    56	
    57	/// A scene: every object, hit in order of distance.
    58	#[derive(Default)]
    59	pub struct HittableList {
    60	    objects: Vec<Box<dyn Hittable>>,
    61	}
    62	
    63	impl HittableList {
    64	    pub fn add(&mut self, object: Box<dyn Hittable>) {
    65	        self.objects.push(object);
    66	    }
    67	}
    68	
    69	impl Hittable for HittableList {
    70	    fn hit(&self, ray: &Ray, t_min: f64, t_max: f64) -> Option<HitRecord> {
    71	        let mut nearest: Option<HitRecord> = None;
    72	        for object in &self.objects {
    73	            let limit = nearest.as_ref().map_or(t_max, |hit| hit.t);
    74	            if let Some(hit) = object.hit(ray, t_min, limit) {
    75	                nearest = Some(hit);
    76	            }
    77	        }
    78	        nearest
    79	    }
    80	}
