    28	/// The colour a ray sees: its scattered path attenuated by each material, the sky gradient when it
    29	/// misses.
    30	fn ray_colour(ray: &Ray, world: &dyn Hittable, rng: &mut Rng) -> Colour {
    31	    let mut ray = *ray;
    32	    let mut colour = Vec3::new(1.0, 1.0, 1.0);
    33	    for _ in 0..MAX_BOUNCES {
    34	        if let Some(hit) = world.hit(&ray, 0.001, f64::INFINITY) {
    35	            match hit.material.scatter(&ray, &hit, rng) {
    36	                Some((attenuation, scattered)) => {
    37	                    colour = colour * attenuation;
    38	                    ray = scattered;
    39	                }
    40	                None => return Vec3::new(0.0, 0.0, 0.0),
    41	            }
    42	        } else {
    43	            return colour * sky_colour(&ray);
    44	        }
    45	    }
    46	    Vec3::new(0.0, 0.0, 0.0)
    47	}
    48	
    49	/// The sky gradient a ray sees when it misses the scene: white at the horizon, blue above.
    50	fn sky_colour(ray: &Ray) -> Colour {
    51	    let t = 0.5 * (ray.direction.unit().y + 1.0);
    52	    Vec3::new(1.0, 1.0, 1.0) * (1.0 - t) + Vec3::new(0.5, 0.7, 1.0) * t
    53	}
