    80	/// Every pixel's colour, row by row from the top, each pixel averaging `samples` jittered rays, with
    81	/// the share of finished rows reported on standard error.
    82	fn render(width: usize, height: usize, samples: usize) -> Vec<Colour> {
    83	    let world = scene();
    84	    let camera = Camera::new(width as f64 / height as f64);
    85	    let mut rng = Rng::new(SEED);
    86	    let mut pixels = Vec::with_capacity(width * height);
    87	    for row in (0..height).rev() {
    88	        for column in 0..width {
    89	            let mut pixel = Vec3::new(0.0, 0.0, 0.0);
    90	            for _ in 0..samples {
    91	                let u = (column as f64 + rng.next_f64()) / width as f64;
    92	                let v = (row as f64 + rng.next_f64()) / height as f64;
    93	                pixel = pixel + ray_colour(&camera.ray(u, v), &world, &mut rng);
    94	            }
    95	            pixels.push(pixel / samples as f64);
    96	        }
    97	    }
    98	    pixels
    99	}
