   101	fn to_byte(channel: f64) -> u8 {
   102	    (255.999 * channel.clamp(0.0, 1.0).sqrt()) as u8
   103	}
   104	
   105	fn write_ppm(
   106	    out: &mut impl Write,
   107	    width: usize,
   108	    height: usize,
   109	    pixels: &[Colour],
   110	) -> io::Result<()> {
   111	    writeln!(out, "P3\n{width} {height}\n255")?;
   112	    for pixel in pixels {
   113	        writeln!(
   114	            out,
   115	            "{} {} {}",
   116	            to_byte(pixel.x),
   117	            to_byte(pixel.y),
   118	            to_byte(pixel.z)
   119	        )?;
   120	    }
   121	    Ok(())
   122	}
