    11	pub struct Sphere {
    12	    pub center: Vec3,
    13	    pub radius: f64,
    14	    pub material: Rc<dyn Material>,
    15	}
    16	
    17	impl Sphere {
    18	    pub fn new(center: Vec3, radius: f64, material: Rc<dyn Material>) -> Self {
    19	        Sphere {
    20	            center,
    21	            radius,
    22	            material,
    23	        }
    24	    }
    25	}
    26	
    27	impl Hittable for Sphere {
    28	    fn hit(&self, ray: &Ray, t_min: f64, t_max: f64) -> Option<HitRecord> {
    29	        let oc = ray.origin - self.center;
    30	        let a = ray.direction.dot(ray.direction);
    31	        let half_b = oc.dot(ray.direction);
    32	        let c = oc.dot(oc) - self.radius * self.radius;
    33	        let discriminant = half_b * half_b - a * c;
    34	        if discriminant < 0.0 {
    35	            return None;
    36	        }
    37	        let root = discriminant.sqrt();
    38	        let mut t = (-half_b - root) / a;
    39	        if t <= t_min || t >= t_max {
    40	            t = (-half_b + root) / a;
    41	            if t <= t_min || t >= t_max {
    42	                return None;
    43	            }
    44	        }
    45	        let point = ray.at(t);
    46	        let outward_normal = (point - self.center) / self.radius;
    47	        let theta = (-outward_normal.y).acos();
    48	        let phi = (-outward_normal.z).atan2(outward_normal.x) + PI;
    49	        let u = phi / (2.0 * PI);
    50	        let v = theta / PI;
    51	        Some(HitRecord::new(
    52	            ray,
    53	            t,
    54	            point,
    55	            outward_normal,
    56	            u,
    57	            v,
    58	            Rc::clone(&self.material),
    59	        ))
    60	    }
    61	}
