    90	
    91	/// The mirror reflection of `v` about the normal `n`.
    92	fn reflect(v: Vec3, n: Vec3) -> Vec3 {
    93	    v - n * (2.0 * v.dot(n))
    94	}
    95	
    96	/// The refracted direction of a unit ray `v` crossing a surface with unit normal `n`, for the
    97	/// ratio `eta_ratio` of the index the ray leaves to the index it enters.
    98	fn refract(v: Vec3, n: Vec3, eta_ratio: f64) -> Vec3 {
    99	    let cos_theta = (-v.dot(n)).min(1.0);
   100	    let perpendicular = (v + n * cos_theta) * eta_ratio;
   101	    let parallel = n * -(1.0 - perpendicular.dot(perpendicular)).max(0.0).sqrt();
   102	    perpendicular + parallel
   103	}
   104	
   105	/// Schlick's approximation of the reflectance at `cosine` for index ratio `eta_ratio`.
   106	fn schlick(cosine: f64, eta_ratio: f64) -> f64 {
   107	    let r0 = (1.0 - eta_ratio) / (1.0 + eta_ratio);
   108	    let r0 = r0 * r0;
   109	    r0 + (1.0 - r0) * (1.0 - cosine).powi(5)
   110	}
   111	
   112	/// A random direction on the unit sphere, drawn by rejection sampling a point in the unit cube.
   113	fn random_unit_vector(rng: &mut Rng) -> Vec3 {
   114	    loop {
   115	        let p = Vec3::new(
   116	            2.0 * rng.next_f64() - 1.0,
   117	            2.0 * rng.next_f64() - 1.0,
   118	            2.0 * rng.next_f64() - 1.0,
   119	        );
   120	        let len_squared = p.dot(p);
   121	        if len_squared > 1e-12 && len_squared <= 1.0 {
   122	            return p.unit();
   123	        }
   124	    }
   125	}
