//! Planes.

use std::rc::Rc;

use crate::hittable::{HitRecord, Hittable};
use crate::material::Material;
use crate::ray::Ray;
use crate::vec3::Vec3;

/// An infinite plane: a point on it and its unit normal.
pub struct Plane {
    pub point: Vec3,
    pub normal: Vec3,
    pub material: Rc<dyn Material>,
}

impl Plane {
    /// Build a plane through `point` with unit normal `normal`.
    pub fn new(point: Vec3, normal: Vec3, material: Rc<dyn Material>) -> Self {
        Plane {
            point,
            normal,
            material,
        }
    }
}

impl Hittable for Plane {
    fn hit(&self, ray: &Ray, t_min: f64, t_max: f64) -> Option<HitRecord> {
        let denominator = ray.direction.dot(self.normal);
        if denominator == 0.0 {
            return None;
        }
        let t = (self.point - ray.origin).dot(self.normal) / denominator;
        if t <= t_min || t >= t_max {
            return None;
        }
        let point = ray.at(t);
        let tangent = if self.normal.x.abs() > self.normal.y.abs() {
            Vec3::new(-self.normal.z, 0.0, self.normal.x).unit()
        } else {
            Vec3::new(0.0, -self.normal.z, self.normal.y).unit()
        };
        let bitangent = self.normal.cross(tangent);
        let u = point.dot(tangent).rem_euclid(1.0);
        let v = point.dot(bitangent).rem_euclid(1.0);
        Some(HitRecord::new(
            ray,
            t,
            point,
            self.normal,
            u,
            v,
            Rc::clone(&self.material),
        ))
    }
}

#[cfg(test)]
mod tests {
    use std::rc::Rc;

    use super::*;
    use crate::material::Lambertian;
    use crate::vec3::Colour;

    #[test]
    fn a_ray_through_the_plane_records_the_hit_and_texture_coordinates_that_wrap() {
        let plane = Plane::new(
            Vec3::new(0.0, 0.0, -2.0),
            Vec3::new(0.0, 0.0, 1.0),
            Rc::new(Lambertian::new(Colour::new(0.8, 0.8, 0.8))),
        );
        let ray = Ray::new(Vec3::new(2.25, -0.5, 0.0), Vec3::new(0.0, 0.0, -1.0));
        let hit = plane.hit(&ray, 0.001, f64::INFINITY).expect("the ray hits");
        assert!((hit.t - 2.0).abs() < 1e-9);
        assert!(hit.front_face);
        assert_eq!(hit.normal, Vec3::new(0.0, 0.0, 1.0));
        assert!((hit.u - 0.5).abs() < 1e-9);
        assert!((hit.v - 0.25).abs() < 1e-9);
    }
}

//! Triangles.

use std::rc::Rc;

use crate::aabb::Aabb;
use crate::hittable::{HitRecord, Hittable};
use crate::material::Material;
use crate::ray::Ray;
use crate::vec3::Vec3;

/// A triangle: its three vertices, counter-clockwise seen from its front face.
pub struct Triangle {
    pub a: Vec3,
    pub b: Vec3,
    pub c: Vec3,
    pub material: Rc<dyn Material>,
}

impl Triangle {
    /// Build a triangle from its three vertices, counter-clockwise seen from its front face.
    pub fn new(a: Vec3, b: Vec3, c: Vec3, material: Rc<dyn Material>) -> Self {
        Triangle { a, b, c, material }
    }
}

impl Hittable for Triangle {
    fn hit(&self, ray: &Ray, t_min: f64, t_max: f64) -> Option<HitRecord> {
        let edge1 = self.b - self.a;
        let edge2 = self.c - self.a;
        let h = ray.direction.cross(edge2);
        let determinant = edge1.dot(h);
        if determinant.abs() < 1e-9 {
            return None;
        }
        let inverse = 1.0 / determinant;
        let s = ray.origin - self.a;
        let u = inverse * s.dot(h);
        if !(0.0..=1.0).contains(&u) {
            return None;
        }
        let q = s.cross(edge1);
        let v = inverse * ray.direction.dot(q);
        if v < 0.0 || u + v > 1.0 {
            return None;
        }
        let t = inverse * edge2.dot(q);
        if t <= t_min || t >= t_max {
            return None;
        }
        let point = ray.at(t);
        let outward_normal = edge1.cross(edge2).unit();
        Some(HitRecord::new(
            ray,
            t,
            point,
            outward_normal,
            u,
            v,
            Rc::clone(&self.material),
        ))
    }

    fn bounding_box(&self) -> Option<Aabb> {
        let min = Vec3::new(
            self.a.x.min(self.b.x).min(self.c.x),
            self.a.y.min(self.b.y).min(self.c.y),
            self.a.z.min(self.b.z).min(self.c.z),
        );
        let max = Vec3::new(
            self.a.x.max(self.b.x).max(self.c.x),
            self.a.y.max(self.b.y).max(self.c.y),
            self.a.z.max(self.b.z).max(self.c.z),
        );
        Some(Aabb::new(min, max))
    }
}

#[cfg(test)]
mod tests {
    use std::rc::Rc;

    use super::*;
    use crate::material::Lambertian;
    use crate::vec3::Colour;

    fn grey_triangle(a: Vec3, b: Vec3, c: Vec3) -> Triangle {
        Triangle::new(
            a,
            b,
            c,
            Rc::new(Lambertian::new(Colour::new(0.8, 0.8, 0.8))),
        )
    }

    #[test]
    fn a_ray_through_the_triangle_hits_its_front_face_with_barycentric_coordinates() {
        let triangle = grey_triangle(
            Vec3::new(0.0, 0.0, -1.0),
            Vec3::new(1.0, 0.0, -1.0),
            Vec3::new(0.0, 1.0, -1.0),
        );
        let ray = Ray::new(Vec3::new(0.25, 0.25, 0.0), Vec3::new(0.0, 0.0, -1.0));
        let hit = triangle
            .hit(&ray, 0.001, f64::INFINITY)
            .expect("the ray hits");
        assert!((hit.t - 1.0).abs() < 1e-9);
        assert!(hit.front_face);
        assert_eq!(hit.normal, Vec3::new(0.0, 0.0, 1.0));
        assert!((hit.u - 0.25).abs() < 1e-9);
        assert!((hit.v - 0.25).abs() < 1e-9);
    }

    #[test]
    fn the_triangle_reports_a_box_around_its_vertices() {
        let triangle = grey_triangle(
            Vec3::new(2.0, -1.0, -3.0),
            Vec3::new(-1.0, 4.0, -2.0),
            Vec3::new(0.5, 0.0, -6.0),
        );
        let bounds = triangle.bounding_box().expect("a triangle has a box");
        assert_eq!(bounds.min, Vec3::new(-1.0, -1.0, -6.0));
        assert_eq!(bounds.max, Vec3::new(2.0, 4.0, -2.0));
    }
}

