    let channels: Vec<u8> = tokens
        .map(|token| token.parse().expect("a channel byte"))
        .collect();
    let pixels: Vec<[u8; 3]> = channels
        .chunks_exact(3)
        .map(|pixel| [pixel[0], pixel[1], pixel[2]])
        .collect();
    assert_eq!(pixels.len(), width * height, "the pixel count");
    pixels
